def safe_filename(inp=None):
    """Safe Filename (dotfiles + ../) | File Helpers | normal 'My File!.txt'->'My_File_.txt' | invalid 123->'123' | empty->'ERROR_EMPTY_INPUT' | none->'ERROR_EMPTY_INPUT' """
    s=str(inp)
    import re
    if not s.strip(): return 'ERROR_EMPTY_INPUT'
    return re.sub(r'[^A-Za-z0-9._-]','_',s)
FEATURES["V13-051"]={"id":"V13-051","name":'Safe Filename (dotfiles + ../)',"category":'File Helpers',"func":safe_filename,"status":"IMPLEMENTED"}
def file_ext(inp=None):
    """File Extension | File Helpers | normal 'photo.jpg'->'jpg' | invalid 'noext'->'' | empty->'ERROR_EMPTY_INPUT' | none->'ERROR_EMPTY_INPUT' """
    s=str(inp).strip()
    if not s: return 'ERROR_EMPTY_INPUT'
    return s.rsplit('.',1)[-1] if '.' in s else ''
FEATURES["V13-052"]={"id":"V13-052","name":'File Extension',"category":'File Helpers',"func":file_ext,"status":"IMPLEMENTED"}
def has_tamil(inp=None):
    """Contains Tamil Range | Text Processing | normal 'vanakkam'->False | invalid 'தமிழ்'->True | empty->'ERROR_EMPTY_INPUT' | none->'ERROR_EMPTY_INPUT' """
    s=str(inp)
    if not s.strip(): return 'ERROR_EMPTY_INPUT'
    return any(0x0B80<=ord(c)<=0x0BFF for c in s)
